  function clipAtPlayhead(){const selected=state.clips.find(x=>x.id===state.selected)||state.textClips.find(x=>x.id===state.selected);if(selected)return selected;return activeClip()||state.textClips.find(x=>state.playhead>=x.start&&state.playhead<x.start+x.duration)||state.clips.find(x=>x.track==='audio'&&state.playhead>=x.start&&state.playhead<x.start+x.duration)||null}
